<?php require_once __DIR__.'/includes/layout.php';if($u=current_user())go($u['rol'].'/dashboard.php');$role=($_GET['rol']??$_POST['rol']??'paciente')==='medico'?'medico':'paciente';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();$curp=strtoupper(trim($_POST['curp']??''));$cedula=trim($_POST['cedula']??'');$especialidad=(int)($_POST['especialidad_id']??0);$birth=birth_from_curp($curp);$pass=$_POST['password']??'';$pass2=$_POST['confirm']??'';$correo=trim($_POST['correo']??'');$tel=trim($_POST['telefono']??'');$nombre=trim($_POST['nombre']??'');$ap=trim($_POST['apellido_paterno']??'');$am=trim($_POST['apellido_materno']??'');
 if(!curp_valid($curp)||!$birth)$error='Revisa la CURP de 18 caracteres y su fecha de nacimiento.';
 elseif($role==='medico'&&!preg_match('/^\d{7,8}$/',$cedula))$error='La cédula debe tener 7 u 8 dígitos.';
 elseif($role==='medico'&&!row('SELECT id FROM especialidades WHERE id=?',[$especialidad]))$error='Selecciona una especialidad médica válida.';
 elseif(!$nombre||!$ap||!$am)$error='Completa tu nombre y apellidos.';
 elseif(!filter_var($correo,FILTER_VALIDATE_EMAIL))$error='Ingresa un correo electrónico válido.';
 elseif(!preg_match('/^\d{10}$/',$tel))$error='El teléfono debe tener 10 dígitos.';
 elseif(!valid_pass($pass))$error='Usa mínimo 9 caracteres, mayúscula, minúscula, número y símbolo.';
 elseif($pass!==$pass2)$error='Las contraseñas no coinciden.';
 elseif(row('SELECT id FROM usuarios WHERE correo=?',[$correo])||row('SELECT usuario_id FROM pacientes WHERE curp=?',[$curp])||row('SELECT usuario_id FROM medicos WHERE curp=?',[$curp]))$error='Ya existe una cuenta con el correo o CURP registrados.';
 elseif($role==='medico'&&row('SELECT usuario_id FROM medicos WHERE cedula=?',[$cedula]))$error='La cédula ya está registrada.';
 else{
  try {db()->beginTransaction();$q=db()->prepare('INSERT INTO usuarios (nombre,apellido_paterno,apellido_materno,correo,telefono,password_hash,rol) VALUES (?,?,?,?,?,?,?)');$q->execute([$nombre,$ap,$am,$correo,$tel,password_hash($pass,PASSWORD_DEFAULT),$role]);$uid=(int)db()->lastInsertId();
  if($role==='paciente'){$q=db()->prepare('INSERT INTO pacientes(usuario_id,curp,fecha_nacimiento) VALUES(?,?,?)');$q->execute([$uid,$curp,$birth]);}
  else {$q=db()->prepare('INSERT INTO medicos(usuario_id,curp,cedula,especialidad_id) VALUES(?,?,?,?)');$q->execute([$uid,$curp,$cedula,$especialidad]);}
  db()->commit();flash('success','Cuenta creada. ¡Bienvenido a MiSalud!'.($role==='medico'?' Un administrador deberá verificar tu documentación.':''));session_regenerate_id(true);$_SESSION['uid']=$uid;go($role.'/dashboard.php');
  }catch(Throwable $ex){if(db()->inTransaction())db()->rollBack();$error='No se pudo completar el registro. Verifica que los datos no estén duplicados.';}
 }
}
$especialidades=all('SELECT id,nombre FROM especialidades ORDER BY nombre');header_ui('Crear cuenta'); ?>
<section class="register-page wrap"><div class="register-intro"><span class="pill">✦ COMIENZA TU EXPERIENCIA</span><h1>Tu salud merece <em>un buen comienzo.</em></h1><p>Regístrate para disfrutar de una experiencia más sencilla y cercana.</p></div><div class="register-card"><h2>Crear una cuenta</h2><p>¿Cómo deseas utilizar MiSalud?</p><div class="role-tabs"><a class="<?=$role==='paciente'?'active':''?>" href="<?=url('registro.php?rol=paciente')?>">♙ Soy paciente</a><a class="<?=$role==='medico'?'active':''?>" href="<?=url('registro.php?rol=medico')?>">✚ Soy médico</a></div><?php if($error):?><div class="alert alert-error"><?=e($error)?></div><?php endif; ?><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="rol" value="<?=$role?>"><?php if($role==='medico'): ?><label>Cédula profesional<input name="cedula" pattern="[0-9]{7,8}" maxlength="8" required placeholder="7 u 8 dígitos" value="<?=e($_POST['cedula']??'')?>"></label><label>Especialidad médica<select name="especialidad_id" required><option value="">Selecciona tu especialidad</option><?php foreach($especialidades as $esp):?><option value="<?=$esp['id']?>" <?=((int)($_POST['especialidad_id']??0)===(int)$esp['id'])?'selected':''?>><?=e($esp['nombre'])?></option><?php endforeach;?></select></label><?php endif; ?><label>CURP<input name="curp" id="curp" maxlength="18" required placeholder="18 caracteres" value="<?=e($_POST['curp']??'')?>"></label><label>Fecha de nacimiento<input id="birth" type="date" disabled><small>Calculada de tu CURP; verifica que sea correcta.</small></label><label>Nombre(s)<input name="nombre" required value="<?=e($_POST['nombre']??'')?>"></label><label>Apellido paterno<input name="apellido_paterno" required value="<?=e($_POST['apellido_paterno']??'')?>"></label><label>Apellido materno<input name="apellido_materno" required value="<?=e($_POST['apellido_materno']??'')?>"></label><label>Teléfono<input name="telefono" type="tel" maxlength="10" pattern="[0-9]{10}" required value="<?=e($_POST['telefono']??'')?>"></label><label>Correo electrónico<input name="correo" type="email" required value="<?=e($_POST['correo']??'')?>"></label><label>Contraseña<div class="password-wrap"><input id="pass" name="password" type="password" required minlength="9"><button type="button" class="toggle-pass" data-target="pass" aria-label="Mostrar contraseña" aria-pressed="false" title="Mostrar contraseña">👁</button></div></label><label>Confirmar contraseña<div class="password-wrap"><input id="confirm" name="confirm" type="password" required minlength="9"><button type="button" class="toggle-pass" data-target="confirm" aria-label="Mostrar contraseña" aria-pressed="false" title="Mostrar contraseña">👁</button></div></label><p class="form-note full">La contraseña requiere mínimo 9 caracteres con mayúscula, minúscula, número y símbolo. La fecha de nacimiento deducida de la CURP es orientativa.</p><button class="btn btn-primary btn-wide full" type="submit">Crear mi cuenta →</button></form><p class="auth-switch">¿Ya tienes cuenta? <a href="<?=url('login.php?rol='.$role)?>">Iniciar sesión</a></p></div></section>
